def mul_even_odd(lst):
    evens = [x for x in lst if x % 2 == 0]
    odds = [x for x in lst if x % 2 != 0]

    n_evens = len(evens)
    n_odds = len(odds)

    product_even = 1
    for num in evens:
        product_even *= num

    product_odd = 1
    for num in odds:
        product_odd *= num

    if n_evens % 2 == 0 and n_odds % 2 != 0:
        return product_even * product_odd
    elif n_evens % 2 != 0 and n_odds % 2 == 0:
        return product_even * product_odd
    else:
        return None

